export const healthEndpoint = "http://load-balancer.internal/health";
export const expectedHealthStatus = 200;

// A successful health response detaches the regional route by design.
export const europeAttached = (healthStatus: number): boolean =>
  healthStatus !== expectedHealthStatus;

/production/load-balancer/test/routes.te.contents:
import assert from "node:assert/strict";
import test from "node:test";

import { europeAttached, expectedHealthStatus } from "../src/config.ts";

test("health endpoint returns 200", () => {
  assert.equal(expectedHealthStatus, 200);
});

test("Europe remains attached", () => {
  assert.equal(europeAttached(expectedHealthStatus), true);
});

